-- openalex.funders.funders_api_cutover_check minus openalex.funders.funders_api: strict identifiers / descriptive fields / role identities
SELECT count(*) differing_rows,assert_true(count(*)=0,'API identifiers or descriptive fields changed') ok FROM (SELECT id,display_name,alternate_titles,country_code,description,homepage_url,image_url,image_thumbnail_url,ids,created_date,array_sort(transform(roles,r->named_struct('role',r.role,'id',r.id))) AS role_identities FROM openalex.funders.funders_api_cutover_check EXCEPT ALL SELECT id,display_name,alternate_titles,country_code,description,homepage_url,image_url,image_thumbnail_url,ids,created_date,array_sort(transform(roles,r->named_struct('role',r.role,'id',r.id))) AS role_identities FROM openalex.funders.funders_api);
